+    assert_eq!(zero.counts(), [0, 0]);
+    let tall = Bitmap::new(0, usize::MAX, &empty).expect("zero width with empty slice");
+    assert_eq!(tall.counts(), [0, 0]);
+    let wide = Bitmap::new(usize::MAX, 0, &empty).expect("max width with empty slice");
