+    fn jumps(arrangement: &Arrangement, cindex: &BTreeMap<usize, usize>) -> Vec<Vec<(usize, i64)>> {
+        let atomics = arrangement.atomics();
+        let mut jump: Vec<Vec<(usize, i64)>> = vec![Vec::new(); arrangement.nhe()];
