        let w = sub(&edge.a, m);
        let tt = cross(&w, &q) / &den;
        let u = cross(&w, n) / &den;
        if tt.is_positive() && !u.is_negative() && u <= Exact::integer(1) {
            Some(tt)
        } else {
            None
        }
    }
}

