fn splits_straddle_line_without_segment_hit_keeps_endpoints() {
    let pt = |x: f64, y: f64| Pt(Exact::from_f64(x).unwrap(), Exact::from_f64(y).unwrap());
    let seg = |ax: f64, ay: f64, bx: f64, by: f64, contour: usize| Seg {
