                    while (!queue.empty()) {
                        size_t cur = queue.front();
                        queue.pop();
                        for (HalfedgeNode *h : members[cur]) {
                            size_t ni = face_id(h->twin()->face());
                            if (!in_mask(ni) && wmask[ni] < 0) {
