                        labels[ni] = count;
                        q.push_back(ni);
                    }
                }
            }
            count += 1;
        }
        (labels, count)
    }

    fn filled(&self) -> &[i32] {
        &self.filled
    }

    fn white(&self) -> &[i32] {
        &self.white
    }

    fn nfilled(&self) -> i32 {
        self.nfilled
    }

    fn nwhite(&self) -> i32 {
        self.nwhite
    }

    fn exterior(&self) -> i32 {
        self.exterior
    }
}

