    fn label(
        nfaces: usize,
        atomics: &[Atomic],
        totals: &[i64],
        keep: impl Fn(i64) -> bool,
    ) -> (Vec<i32>, i32) {
        let mut labels = vec![-1i32; nfaces];
        let mut count = 0i32;
        for f in 0..nfaces {
